    MA([("gaan over","ser sobre"),("hoofdpersoon","protagonista"),("afloop","desfecho"),("verrassend","surpreendente")], "Falar de filmes.", ["v-gaan-over","v-hoofdpersoon","v-afloop","v-verrassend"]),
    TR("pt-nl","O filme era sobre uma família em Lisboa.", ["De film ging over een familie in Lissabon","De film gaat over een familie in Lissabon"], "gaan over = ser sobre.", ["v-gaan-over"]),
    MC("«Waar ging de film over?» pergunta…", ["*de que tratava o filme","onde passava o filme|Seria «Waar draaide de film?»","quando acabou o filme|Não."], "Waar … over? = sobre o quê?", ["v-gaan-over"]),
    AR("hoofdpersoon","o protagonista","de", "De persoon → de hoofdpersoon.", ["v-hoofdpersoon"]),
    FB("Ik verwachtte een happy end, maar de ___ was heel verdrietig.", ["afloop"], "afloop = desfecho.", ["v-afloop"], choices=["afloop","hoofdpersoon","begin"], tr="Esperava um final feliz, mas o desfecho foi muito triste."),
    CO("text","Wat zag jij dit weekend?", "Zaterdag zag ik een Nederlandse film, «Bankier van het verzet». De film ging over Walraven van Hall, een bankier in de Tweede Wereldoorlog. Hij financierde in het geheim het verzet tegen de Duitsers. De hoofdpersoon was moedig en slim, maar de afloop was tragisch. Ik vond de film spannend en leerzaam, want ik wist niets van deze geschiedenis.",
       [("Sobre quem era o filme?", ["*Um banqueiro que financiou a resistência","Um soldado alemão","Um rei holandês"]),("Como era o final?", ["*Trágico","Feliz","Engraçado"]),("Porque achou o filme instrutivo?", ["*Não conhecia esta história","Já tinha visto o filme","Era uma comédia"])],
       "Resumo no imperfectum: ging over, financierde, was.", ["v-gaan-over","v-hoofdpersoon"]),
