    DL([("Agent","Heeft u iets gezien?","Viu alguma coisa?"),("Buurvrouw","","")], ["*Ja, rond drie uur zag ik twee mannen wegrennen met een rugzak.","Ja, ik zie morgen iets.|Não faz sentido.","Nee, ik heb geen rugzak.|Não responde."], "Testemunho no passado.", ["v-inbreker"]),
    LI("Er werd ingebroken terwijl wij op vakantie waren.", ["Er werd ingebroken terwijl wij op vakantie waren","Er werd ingebroken terwijl we op vakantie waren"], "Houve um assalto enquanto estávamos de férias.", "terwijl = enquanto (verbo no fim).", ["v-inbreken"]),
