       [("O que contou o Mark?", ["*Que a Petra se despediu","Que a Petra foi promovida","Que ele vai para Londres"]),("Porque se terá despedido?", ["*Arranjou trabalho em Londres","Foi despedida","Vai ter um bebé"]),("O que pede a Ilse?", ["*Que o Rui ainda não espalhe","Que o Rui fale com a Petra","Que o Rui conte ao chefe"])],
